private async clickTeachAppCard(page) {
  // Try each candidate selector while the card is already visible.
  for (const sel of SEL.teachingCard) {   // a LIST of selectors: survives a card rename
    const card = page.locator(sel).first();
    if (await card.isVisible({ timeout: 2000 }).catch(() => false)) {   // .catch(false): a miss continues, doesn't throw
      await card.click();
      return true;
    }
  }
  // Card hidden in a carousel — swipe until it appears
  const carousel = page.locator(SEL.skillCarousel).first();
  const box = await carousel.boundingBox();
  for (let i = 0; i < 8; i++) {   // bounded at 8 swipes so a truly-absent card can't loop forever
    // Real drag right-edge -> left-edge; steps:10 makes it incremental so it
    // registers as a swipe gesture (a single jump often won't).
    await page.mouse.move(box.x + box.width - 20, box.y + box.height / 2);
    await page.mouse.down();
    await page.mouse.move(box.x + 20, box.y + box.height / 2, { steps: 10 });
    await page.mouse.up();
    for (const sel of SEL.teachingCard) {   // re-check after each swipe, click the instant it shows
      const card = page.locator(sel).first();
      if (await card.isVisible({ timeout: 1000 }).catch(() => false)) {
        await card.click();
        return true;
      }
    }
  }
  return false;   // 8 swipes, still nothing -> caller reports 'card not found'
}

private async waitForLLMResponse(page, timeout) {
  const generating = page.locator('text=Generating Summary');
  const thinking = page.locator('text=Thinking...');
  const stopBtn = page.locator('button:has-text("Stop")');

  // RISING edge: race -> proceed as soon as ANY indicator appears, confirming
  // classification started (guards against reading the DOM too early).
  await Promise.race([
    generating.waitFor({ state: 'visible', timeout: 20000 }),
    thinking.waitFor({ state: 'visible', timeout: 20000 }),
    stopBtn.waitFor({ state: 'visible', timeout: 20000 }),
  ]).catch(() => {});   // a never-appearing indicator (instant/cached result) must not fail the run

  // FALLING edge: all -> require EVERY indicator hidden, since different phases
  // show different ones; not done until all are gone.
  await Promise.all([
    generating.waitFor({ state: 'hidden', timeout }).catch(() => {}),
    thinking.waitFor({ state: 'hidden', timeout }).catch(() => {}),
    stopBtn.waitFor({ state: 'hidden', timeout }).catch(() => {}),
  ]);
  await page.waitForTimeout(5000); // indicators vanish a beat before the labels paint — let them finish
}

private async captureITPercentage(page) {
  const pageText = (await page.textContent('body')) || '';

  // Anchor to the literal phrase so '90% Marketing' can't be mistaken for an IT score.
  // "X% Information Technology" -> that's the real IT score
  const itMatch = pageText.match(/(\d{1,3})%\s+Information Technology/i);   // \d{1,3} bounds to a 0-100 %
  if (itMatch) return parseInt(itMatch[1], 10);   // base-10 pinned so a leading zero isn't read as octal

  // A percentage on a DIFFERENT named category -> confidently 0% IT (distinct from null).
  const nonItMatch = pageText.match(/(\d{1,3})%\s+(?:Marketing|Finance|Sales|Operations)/i);
  if (nonItMatch) return 0;

  return null;   // no recognized category -> null == scrape failure, NOT the same as a real 0
}

private async captureContentAudience(page) {
  const result = { businessLine: [], region: [], corporateFunction: [], role: [] };
  const fields = [
    { label: 'Business Line', key: 'businessLine' },
    { label: 'Region', key: 'region' },
    { label: 'Corporate Function', key: 'corporateFunction' },
    { label: 'Role', key: 'role' },
  ];

  for (const field of fields) {
    // Strategy 1: the semantic component-library structure, anchored by visible label text.
    let chips = await page.locator(`form-field:has(field-label:has-text("${field.label}"))`).locator('.k-chip').all();
    if (chips.length === 0) {
      // Strategy 2 (only if 1 found nothing): looser label + xpath=.. walk to the parent.
      chips = await page.locator(`label:has-text("${field.label}")`).locator('xpath=..').locator('.k-chip').all();
    }
    for (const chip of chips) {
      const text = (await chip.textContent().catch(() => ''))?.trim();   // guard + trim
      if (text) result[field.key].push(text);   // push only non-empty, so a stray empty chip doesn't pollute
    }
  }
  // Region is the field most reliably present on a real classification, so its
  // emptiness is the proxy for 'all DOM strategies failed' -> raw-text fallback.
  if (result.region.length === 0) await this.parseContentAudienceFromText(page, result);
  return result;
}

private evaluateResult(result, sampleDef) {
  // NON-PII sample: an unexpected guardrail trip is a WARN (worth surfacing) not a FAIL.
  // Match the EXACT banner string so innocent prose doesn't over-match.
  if (sampleDef.testNum !== PII_TEST_NUM) {
    const flagged = result.response.toLowerCase().includes('pii or conflicts have been detected');
    if (flagged) {
      result.status = 'WARN';
      result.statusReason = 'Privacy guardrail triggered unexpectedly';
      return;
    }
  }

  // PII sample: inverted expectation — it SHOULD trip. Broad regex on purpose: a
  // missed guardrail is a privacy incident, so accept the widest evidence it fired.
  if (sampleDef.testNum === PII_TEST_NUM) {
    const blocked = /pii|personal|sensitive|redact|privacy/i.test(result.response);
    result.status = blocked ? 'PASS' : 'FAIL';   // a miss here is a hard FAIL
    result.statusReason = blocked ? 'Guardrail triggered correctly' : 'Guardrail did NOT trigger';
    return;
  }

  // Ordinary case: pass only if it landed in the IT bucket. ?? 0 coerces a null
  // (scrape failure) below threshold -> WARN, so unread labels are never silently passed.
  result.status = (result.itClassificationPct ?? 0) >= 70 ? 'PASS' : 'WARN';
}
